import static org.junit.Assert.*;

/**
 * Unit tests for StrBuilder.indexOf(String str, int startIndex)
 * Designed to maximize branch and line coverage.
 */
public class StrBuilder_indexOf_TriageGen1Test {

    private StrBuilder strBuilder;

    @Before
    public void setUp() {
        strBuilder = new StrBuilder();
    }

    @Test
    public void testIndexOf_NegativeStartIndex() {
        strBuilder.append("hello");
        // startIndex < 0 should be treated as 0
        Assert.assertEquals(0, strBuilder.indexOf("hello", -1));
        Assert.assertEquals(1, strBuilder.indexOf("ello", -10));
    }
























}

